interface UserPreferences {
  theme: string
  language: string
  notifications: boolean
}

// User-specific data, so it must never be cached or prerendered.
// `cache: 'no-store'` opts this fetch out of the persistent cache and makes the
// route dynamic — without it the default `auto no cache` would fetch once at build.
async function getUserPreferences(): Promise<UserPreferences> {
  try {
    const res = await fetch('https://api.example.com/user/preferences', {
      cache: 'no-store',
    })
    if (!res.ok) throw new Error(`Request failed: ${res.status}`)
    return res.json()
  } catch {
    // Return mock data for build time
    return { theme: 'light', language: 'en', notifications: true }
  }
}

export default async function UserDashboard() {
  const preferences = await getUserPreferences()

  return (
    <div>
      <h2>User Dashboard</h2>
      <ul>
        <li>Theme: {preferences.theme}</li>
        <li>Language: {preferences.language}</li>
        <li>Notifications: {preferences.notifications ? 'On' : 'Off'}</li>
      </ul>
    </div>
  )
}

